window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-602067ecaeca6343"]={"versions": [{"id": "FIG-602067ecaeca6343", "releases": ["R4.1.3", "R20-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Strukturelles Kompositionsdiagramm (UML-basiertes Software-Architekturmodell gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Kapitel <em>Component Modeling & Connectors</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Das Diagramm illustriert das architektonische Entwurfsmuster für einen <strong><code>PassThroughSwConnector</code> innerhalb eines hierarchischen Subsystems</strong> (<code>CompositionSwComponentType</code>), kombiniert mit einem <strong><code>PortInterfaceMapping</code></strong>.</li>\n<li><strong>Funktionale Problemstellung (Use Case II):</strong> Ein Teilsystem wird als <code>CompositionSwComponentType</code> gekapselt, welches interne atomare Logik (<code>ApplicationSwComponentType</code>) beherbergt. Gleichzeitig müssen Schnittstellen benachbarter Komponenten das Subsystem lediglich rein transitiv durchqueren (Pass-Through), weisen jedoch strukturelle oder semantische Inkompatibilitäten auf (z. B. unterschiedliche Elementnamen, Datentypen oder Skalierungen).</li>\n<li><strong>Lösungsansatz:</strong> Anstelle einer ressourcenintensiven „Forwarder-/Bypass-SW-C“ im C-Code verbindet ein <code>PassThroughSwConnector</code> den eingehenden mit dem ausgehenden Outer-Port der Komposition direkt auf VFB-Ebene. Die Schnittstellenanpassung erfolgt deklarativ über ein assoziiertes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Rollen</p>\n<ol class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (Blauer Außenrahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Enthält drei externe Komponenteninstanzen (<code>SwComponentPrototype</code>s, blau dargestellt) sowie das zentrale Subsystem.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subsystem-Komposition (Mittlerer schwarzer Rahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Beherbergt:</li>\n<li>Einen internen <code>ApplicationSwComponentType</code> (atomare Softwarekomponente mit interner Verhaltensbeschreibung / <code>SwcInternalBehavior</code>).</li>\n<li>Einen deklarativen VFB-Kanal: <code>PassThroughSwConnector</code>.</li>\n<li>Ein zugeordnetes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Externe Instanzen (<code>SwComponentPrototype</code>s, blau):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Oben links:</strong> Quelle/Senke einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n<li><strong>Unten links:</strong> Sender/Provider einer datenbasierten Schnittstelle (Symbol <code>|&gt;</code>).</li>\n<li><strong>Rechts:</strong> Senke/Quelle einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellentypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>&gt;&gt;</code> (Doppel-Chevron / TriggerInterface bzw. ModeSwitchInterface):</strong></li>\n<li>Kennzeichnet eine Trigger- oder Modus-Umschalt-Schnittstelle.</li>\n<li>Eingehender Port links am Subsystem: <code>RPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li>Ausgehender Port rechts am Subsystem: <code>PPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li><strong><code>|&gt;</code> (Dreiecks-Symbol / SenderReceiverInterface):</strong></li>\n<li>Klassische Daten-Schnittstelle (Sender/Receiver).</li>\n<li>Unterer linker Port: Führt von der externen Komponente direkt in die interne <code>ApplicationSwComponentType</code> (terminiert in der atomaren Logik).</li>\n</ul>\n<p class=\"fig-p\">#### Verbinder & Zuordnungen (Konnektoren & Metamodell-Relationen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>AssemblySwConnector</code> (blaue Verbindungslinien):</strong></li>\n<li>Verbindet die äußeren <code>SwComponentPrototype</code>s mit den Außen-Ports (<code>PortPrototype</code>s) des zentralen <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PassThroughSwConnector</code> (horizontale durchgehende Linie im Subsystem):</strong></li>\n<li>Spezialisierung von <code>SwConnector</code> (<code>providedOuterPort: PPortPrototype [1]</code>, <code>requiredOuterPort: RPortPrototype [1]</code>).</li>\n<li>Verbindet zwei äußere Ports <strong>desselben</strong> <code>CompositionSwComponentType</code> unmittelbar miteinander, ohne eine interne atomare Instanz zu durchlaufen.</li>\n<li><strong><code>PortInterfaceMapping</code> (gestrichelte Abhängigkeitsrelation / Dependency):</strong></li>\n<li>Aggregation/Assoziation: <code>SwConnector.mapping [0..1] -&gt; PortInterfaceMapping</code>.</li>\n<li>Löst strukturelle Differenzen zwischen den Interfaces der beiden verbundenen Outer-Ports auf (z. B. <code>VariableDataPrototypeMapping</code>, <code>ClientServerOperationMapping</code> oder <code>ModeDeclarationMapping</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Signalfluss</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Strukturmodell – Dynamik zur Laufzeit (VFB / RTE):</strong></li>\n<li><strong>Pfad 1 (Anwendungslogik, unten):</strong> Signalfluss verläuft von der unteren linken Komponente über den <code>AssemblySwConnector</code> in den Outer-Port der Komposition, wird per Delegation an die <code>ApplicationSwComponentType</code> übergeben und triggert dort ein <code>RunnableEntity</code> via RTE Event (<code>DataReceivedEvent</code>).</li>\n<li><strong>Pfad 2 (Pass-Through, oben):</strong> Signal/Trigger von der oberen linken Komponente trifft auf den Outer-Port des Subsystems. Der <code>PassThroughSwConnector</code> leitet die Kommunikation unter Umgehung jeglicher CPU-Tasks direkt an den rechten Outer-Port weiter.</li>\n<li><strong>Kein Scheduling-/RTE-Overhead:</strong></li>\n<li>Es existiert <strong>kein OS-Task</strong>, <strong>kein Runnable</strong> und <strong>kein Puffer-Kopierzyklus</strong> innerhalb des Subsystems für den oberen Pfad.</li>\n<li>Die RTE löst die Verbindung bei der Generierung (<code>Rte_Write</code> -> <code>Rte_Read</code> bzw. direkte Funktionsaufrufe / Task-Aktivierungen) direkt zwischen der Quell- und Zielkomponente auf, als ob die Kompositionshierarchie flach wäre.</li>\n<li><strong>Mapping-Transformation:</strong></li>\n<li>Falls Konvertierungen (z. B. Skalierungsfaktoren, Record-Element-Verschiebungen) definiert sind, generiert der RTE-Generator Inline-Transformationscode direkt in die Kommunikationsschnittstelle der beteiligten Endpunkte.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anti-Pattern-Vermeidung:</strong></li>\n<li>Verhindert das veraltete Architektur-Anti-Pattern, eine leere atomare Dummy-SW-C („Router-SW-C“ / „Forwarder“) zu implementieren, die Signale nur empfängt und 1:1 wieder wegschreibt. Das spart RAM, Flash, CPU-Last und vermeidet Latenzen/Jitter.</li>\n<li><strong>Hierarchische Kapselung:</strong></li>\n<li>Ermöglicht sauberes Subsystem-Packaging: Eine Zulieferer- oder Funktions-Komposition kann Ports nach außen exponieren, die intern nur durchgeschleift werden, ohne das interne Implementierungsgeheimnis der Komposition zu verletzen.</li>\n<li><strong>Einschränkungen & Validierungsregeln (AUTOSAR Validierung / ARXML-Prüfung):</strong></li>\n<li>Ein <code>PassThroughSwConnector</code> darf <strong>ausschließlich</strong> innerhalb eines <code>CompositionSwComponentType</code> deklariert werden; atomare Komponenten besitzen keine Connectors.</li>\n<li>Die beiden verknüpften Ports müssen zwingend kompatible Rollen besitzen (ein <code>RPortPrototype</code> und ein <code>PPortPrototype</code>). Zwei P-Ports oder zwei R-Ports können nicht direkt verbunden werden.</li>\n<li>Wenn die Interface-Definitionen divergieren (z. B. unterschiedliche Elementnamen oder Datentypen), verlangt das Schema zwingend ein valides <code>PortInterfaceMapping</code> (<code>[TPS_SWCT_01160]</code>, <code>[TPS_SWCT_01161]</code>), andernfalls schlägt die VFB-Validierung mit Inkompatibilitätsfehlern fehl.</li>\n<li><strong>Allokation auf ECUs (System Description vs. ECU Extract):</strong></li>\n<li>Wird das Subsystem auf eine einzige ECU gemappt, eliminiert der RTE-Generator die hierarchischen Grenzen vollständig („Flattening“).</li>\n<li>Werden die Quell- und Zielkomponenten über verschiedene ECUs verteilt, wird der Pass-Through auf die Com- bzw. Signal-Gateway-Ebene des Basis-Software-Stacks (BSW / PduR / Com) übertragen.</li>\n</ul>"}, {"id": "FIG-6d6be4e06feb97e1", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Strukturelles Kompositionsdiagramm (UML-basiertes Software-Architekturmodell gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Kapitel <em>Component Modeling & Connectors</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Das Diagramm illustriert das architektonische Entwurfsmuster für einen <strong><code>PassThroughSwConnector</code> innerhalb eines hierarchischen Subsystems</strong> (<code>CompositionSwComponentType</code>), kombiniert mit einem <strong><code>PortInterfaceMapping</code></strong>.</li>\n<li><strong>Funktionale Problemstellung (Use Case II):</strong> Ein Teilsystem wird als <code>CompositionSwComponentType</code> gekapselt, welches interne atomare Logik (<code>ApplicationSwComponentType</code>) beherbergt. Gleichzeitig müssen Schnittstellen benachbarter Komponenten das Subsystem lediglich rein transitiv durchqueren (Pass-Through), weisen jedoch strukturelle oder semantische Inkompatibilitäten auf (z. B. unterschiedliche Elementnamen, Datentypen oder Skalierungen).</li>\n<li><strong>Lösungsansatz:</strong> Anstelle einer ressourcenintensiven „Forwarder-/Bypass-SW-C“ im C-Code verbindet ein <code>PassThroughSwConnector</code> den eingehenden mit dem ausgehenden Outer-Port der Komposition direkt auf VFB-Ebene. Die Schnittstellenanpassung erfolgt deklarativ über ein assoziiertes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Rollen</p>\n<ol class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (Blauer Außenrahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Enthält drei externe Komponenteninstanzen (<code>SwComponentPrototype</code>s, blau dargestellt) sowie das zentrale Subsystem.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subsystem-Komposition (Mittlerer schwarzer Rahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Beherbergt:</li>\n<li>Einen internen <code>ApplicationSwComponentType</code> (atomare Softwarekomponente mit interner Verhaltensbeschreibung / <code>SwcInternalBehavior</code>).</li>\n<li>Einen deklarativen VFB-Kanal: <code>PassThroughSwConnector</code>.</li>\n<li>Ein zugeordnetes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Externe Instanzen (<code>SwComponentPrototype</code>s, blau):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Oben links:</strong> Quelle/Senke einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n<li><strong>Unten links:</strong> Sender/Provider einer datenbasierten Schnittstelle (Symbol <code>|&gt;</code>).</li>\n<li><strong>Rechts:</strong> Senke/Quelle einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellentypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>&gt;&gt;</code> (Doppel-Chevron / TriggerInterface bzw. ModeSwitchInterface):</strong></li>\n<li>Kennzeichnet eine Trigger- oder Modus-Umschalt-Schnittstelle.</li>\n<li>Eingehender Port links am Subsystem: <code>RPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li>Ausgehender Port rechts am Subsystem: <code>PPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li><strong><code>|&gt;</code> (Dreiecks-Symbol / SenderReceiverInterface):</strong></li>\n<li>Klassische Daten-Schnittstelle (Sender/Receiver).</li>\n<li>Unterer linker Port: Führt von der externen Komponente direkt in die interne <code>ApplicationSwComponentType</code> (terminiert in der atomaren Logik).</li>\n</ul>\n<p class=\"fig-p\">#### Verbinder & Zuordnungen (Konnektoren & Metamodell-Relationen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>AssemblySwConnector</code> (blaue Verbindungslinien):</strong></li>\n<li>Verbindet die äußeren <code>SwComponentPrototype</code>s mit den Außen-Ports (<code>PortPrototype</code>s) des zentralen <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PassThroughSwConnector</code> (horizontale durchgehende Linie im Subsystem):</strong></li>\n<li>Spezialisierung von <code>SwConnector</code> (<code>providedOuterPort: PPortPrototype [1]</code>, <code>requiredOuterPort: RPortPrototype [1]</code>).</li>\n<li>Verbindet zwei äußere Ports <strong>desselben</strong> <code>CompositionSwComponentType</code> unmittelbar miteinander, ohne eine interne atomare Instanz zu durchlaufen.</li>\n<li><strong><code>PortInterfaceMapping</code> (gestrichelte Abhängigkeitsrelation / Dependency):</strong></li>\n<li>Aggregation/Assoziation: <code>SwConnector.mapping [0..1] -&gt; PortInterfaceMapping</code>.</li>\n<li>Löst strukturelle Differenzen zwischen den Interfaces der beiden verbundenen Outer-Ports auf (z. B. <code>VariableDataPrototypeMapping</code>, <code>ClientServerOperationMapping</code> oder <code>ModeDeclarationMapping</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Strukturmodell – Dynamik zur Laufzeit (VFB / RTE):</strong></li>\n<li><strong>Pfad 1 (Anwendungslogik, unten):</strong> Signalfluss verläuft von der unteren linken Komponente über den <code>AssemblySwConnector</code> in den Outer-Port der Komposition, wird per Delegation an die <code>ApplicationSwComponentType</code> übergeben und triggert dort ein <code>RunnableEntity</code> via RTE Event (<code>DataReceivedEvent</code>).</li>\n<li><strong>Pfad 2 (Pass-Through, oben):</strong> Signal/Trigger von der oberen linken Komponente trifft auf den Outer-Port des Subsystems. Der <code>PassThroughSwConnector</code> leitet die Kommunikation unter Umgehung jeglicher CPU-Tasks direkt an den rechten Outer-Port weiter.</li>\n<li><strong>Kein Scheduling-/RTE-Overhead:</strong></li>\n<li>Es existiert <strong>kein OS-Task</strong>, <strong>kein Runnable</strong> und <strong>kein Puffer-Kopierzyklus</strong> innerhalb des Subsystems für den oberen Pfad.</li>\n<li>Die RTE löst die Verbindung bei der Generierung (<code>Rte_Write</code> -> <code>Rte_Read</code> bzw. direkte Funktionsaufrufe / Task-Aktivierungen) direkt zwischen der Quell- und Zielkomponente auf, als ob die Kompositionshierarchie flach wäre.</li>\n<li><strong>Mapping-Transformation:</strong></li>\n<li>Falls Konvertierungen (z. B. Skalierungsfaktoren, Record-Element-Verschiebungen) definiert sind, generiert der RTE-Generator Inline-Transformationscode direkt in die Kommunikationsschnittstelle der beteiligten Endpunkte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anti-Pattern-Vermeidung:</strong></li>\n<li>Verhindert das veraltete Architektur-Anti-Pattern, eine leere atomare Dummy-SW-C („Router-SW-C“ / „Forwarder“) zu implementieren, die Signale nur empfängt und 1:1 wieder wegschreibt. Das spart RAM, Flash, CPU-Last und vermeidet Latenzen/Jitter.</li>\n<li><strong>Hierarchische Kapselung:</strong></li>\n<li>Ermöglicht sauberes Subsystem-Packaging: Eine Zulieferer- oder Funktions-Komposition kann Ports nach außen exponieren, die intern nur durchgeschleift werden, ohne das interne Implementierungsgeheimnis der Komposition zu verletzen.</li>\n<li><strong>Einschränkungen & Validierungsregeln (AUTOSAR Validierung / ARXML-Prüfung):</strong></li>\n<li>Ein <code>PassThroughSwConnector</code> darf <strong>ausschließlich</strong> innerhalb eines <code>CompositionSwComponentType</code> deklariert werden; atomare Komponenten besitzen keine Connectors.</li>\n<li>Die beiden verknüpften Ports müssen zwingend kompatible Rollen besitzen (ein <code>RPortPrototype</code> und ein <code>PPortPrototype</code>). Zwei P-Ports oder zwei R-Ports können nicht direkt verbunden werden.</li>\n<li>Wenn die Interface-Definitionen divergieren (z. B. unterschiedliche Elementnamen oder Datentypen), verlangt das Schema zwingend ein valides <code>PortInterfaceMapping</code> (<code>[TPS_SWCT_01160]</code>, <code>[TPS_SWCT_01161]</code>), andernfalls schlägt die VFB-Validierung mit Inkompatibilitätsfehlern fehl.</li>\n<li><strong>Allokation auf ECUs (System Description vs. ECU Extract):</strong></li>\n<li>Wird das Subsystem auf eine einzige ECU gemappt, eliminiert der RTE-Generator die hierarchischen Grenzen vollständig („Flattening“).</li>\n<li>Werden die Quell- und Zielkomponenten über verschiedene ECUs verteilt, wird der Pass-Through auf die Com- bzw. Signal-Gateway-Ebene des Basis-Software-Stacks (BSW / PduR / Com) übertragen.</li>\n</ul>"}, {"id": "FIG-5f57fe155affcc1b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Strukturelles Kompositionsdiagramm (UML-basiertes Software-Architekturmodell gemäß <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Kapitel <em>Component Modeling & Connectors</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Das Diagramm illustriert das architektonische Entwurfsmuster für einen <strong><code>PassThroughSwConnector</code> innerhalb eines hierarchischen Subsystems</strong> (<code>CompositionSwComponentType</code>), kombiniert mit einem <strong><code>PortInterfaceMapping</code></strong>.</li>\n<li><strong>Funktionale Problemstellung (Use Case II):</strong> Ein Teilsystem wird als <code>CompositionSwComponentType</code> gekapselt, welches interne atomare Logik (<code>ApplicationSwComponentType</code>) beherbergt. Gleichzeitig müssen Schnittstellen benachbarter Komponenten das Subsystem lediglich rein transitiv durchqueren (Pass-Through), weisen jedoch strukturelle oder semantische Inkompatibilitäten auf (z. B. unterschiedliche Elementnamen, Datentypen oder Skalierungen).</li>\n<li><strong>Lösungsansatz:</strong> Anstelle einer ressourcenintensiven „Forwarder-/Bypass-SW-C“ im C-Code verbindet ein <code>PassThroughSwConnector</code> den eingehenden mit dem ausgehenden Outer-Port der Komposition direkt auf VFB-Ebene. Die Schnittstellenanpassung erfolgt deklarativ über ein assoziiertes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Rollen</p>\n<ol class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (Blauer Außenrahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Enthält drei externe Komponenteninstanzen (<code>SwComponentPrototype</code>s, blau dargestellt) sowie das zentrale Subsystem.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subsystem-Komposition (Mittlerer schwarzer Rahmen):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Metamodell-Typ: <code>CompositionSwComponentType</code>.</li>\n<li>Beherbergt:</li>\n<li>Einen internen <code>ApplicationSwComponentType</code> (atomare Softwarekomponente mit interner Verhaltensbeschreibung / <code>SwcInternalBehavior</code>).</li>\n<li>Einen deklarativen VFB-Kanal: <code>PassThroughSwConnector</code>.</li>\n<li>Ein zugeordnetes <code>PortInterfaceMapping</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Externe Instanzen (<code>SwComponentPrototype</code>s, blau):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Oben links:</strong> Quelle/Senke einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n<li><strong>Unten links:</strong> Sender/Provider einer datenbasierten Schnittstelle (Symbol <code>|&gt;</code>).</li>\n<li><strong>Rechts:</strong> Senke/Quelle einer ereignis- oder zustandsbasierten Schnittstelle (Symbol <code>&gt;&gt;</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Schnittstellentypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>&gt;&gt;</code> (Doppel-Chevron / TriggerInterface bzw. ModeSwitchInterface):</strong></li>\n<li>Kennzeichnet eine Trigger- oder Modus-Umschalt-Schnittstelle.</li>\n<li>Eingehender Port links am Subsystem: <code>RPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li>Ausgehender Port rechts am Subsystem: <code>PPortPrototype</code> (bzw. <code>PRPortPrototype</code>).</li>\n<li><strong><code>|&gt;</code> (Dreiecks-Symbol / SenderReceiverInterface):</strong></li>\n<li>Klassische Daten-Schnittstelle (Sender/Receiver).</li>\n<li>Unterer linker Port: Führt von der externen Komponente direkt in die interne <code>ApplicationSwComponentType</code> (terminiert in der atomaren Logik).</li>\n</ul>\n<p class=\"fig-p\">#### Verbinder & Zuordnungen (Konnektoren & Metamodell-Relationen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>AssemblySwConnector</code> (blaue Verbindungslinien):</strong></li>\n<li>Verbindet die äußeren <code>SwComponentPrototype</code>s mit den Außen-Ports (<code>PortPrototype</code>s) des zentralen <code>CompositionSwComponentType</code>.</li>\n<li><strong><code>PassThroughSwConnector</code> (horizontale durchgehende Linie im Subsystem):</strong></li>\n<li>Spezialisierung von <code>SwConnector</code> (<code>providedOuterPort: PPortPrototype [1]</code>, <code>requiredOuterPort: RPortPrototype [1]</code>).</li>\n<li>Verbindet zwei äußere Ports <strong>desselben</strong> <code>CompositionSwComponentType</code> unmittelbar miteinander, ohne eine interne atomare Instanz zu durchlaufen.</li>\n<li><strong><code>PortInterfaceMapping</code> (gestrichelte Abhängigkeitsrelation / Dependency):</strong></li>\n<li>Aggregation/Assoziation: <code>SwConnector.mapping [0..1] -&gt; PortInterfaceMapping</code>.</li>\n<li>Löst strukturelle Differenzen zwischen den Interfaces der beiden verbundenen Outer-Ports auf (z. B. <code>VariableDataPrototypeMapping</code>, <code>ClientServerOperationMapping</code> oder <code>ModeDeclarationMapping</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Strukturmodell – Dynamik zur Laufzeit (VFB / RTE):</strong></li>\n<li><strong>Pfad 1 (Anwendungslogik, unten):</strong> Signalfluss verläuft von der unteren linken Komponente über den <code>AssemblySwConnector</code> in den Outer-Port der Komposition, wird per Delegation an die <code>ApplicationSwComponentType</code> übergeben und triggert dort ein <code>RunnableEntity</code> via RTE Event (<code>DataReceivedEvent</code>).</li>\n<li><strong>Pfad 2 (Pass-Through, oben):</strong> Signal/Trigger von der oberen linken Komponente trifft auf den Outer-Port des Subsystems. Der <code>PassThroughSwConnector</code> leitet die Kommunikation unter Umgehung jeglicher CPU-Tasks direkt an den rechten Outer-Port weiter.</li>\n<li><strong>Kein Scheduling-/RTE-Overhead:</strong></li>\n<li>Es existiert <strong>kein OS-Task</strong>, <strong>kein Runnable</strong> und <strong>kein Puffer-Kopierzyklus</strong> innerhalb des Subsystems für den oberen Pfad.</li>\n<li>Die RTE löst die Verbindung bei der Generierung (<code>Rte_Write</code> -> <code>Rte_Read</code> bzw. direkte Funktionsaufrufe / Task-Aktivierungen) direkt zwischen der Quell- und Zielkomponente auf, als ob die Kompositionshierarchie flach wäre.</li>\n<li><strong>Mapping-Transformation:</strong></li>\n<li>Falls Konvertierungen (z. B. Skalierungsfaktoren, Record-Element-Verschiebungen) definiert sind, generiert der RTE-Generator Inline-Transformationscode direkt in die Kommunikationsschnittstelle der beteiligten Endpunkte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anti-Pattern-Vermeidung:</strong></li>\n<li>Verhindert das veraltete Architektur-Anti-Pattern, eine leere atomare Dummy-SW-C („Router-SW-C“ / „Forwarder“) zu implementieren, die Signale nur empfängt und 1:1 wieder wegschreibt. Das spart RAM, Flash, CPU-Last und vermeidet Latenzen/Jitter.</li>\n<li><strong>Hierarchische Kapselung:</strong></li>\n<li>Ermöglicht sauberes Subsystem-Packaging: Eine Zulieferer- oder Funktions-Komposition kann Ports nach außen exponieren, die intern nur durchgeschleift werden, ohne das interne Implementierungsgeheimnis der Komposition zu verletzen.</li>\n<li><strong>Einschränkungen & Validierungsregeln (AUTOSAR Validierung / ARXML-Prüfung):</strong></li>\n<li>Ein <code>PassThroughSwConnector</code> darf <strong>ausschließlich</strong> innerhalb eines <code>CompositionSwComponentType</code> deklariert werden; atomare Komponenten besitzen keine Connectors.</li>\n<li>Die beiden verknüpften Ports müssen zwingend kompatible Rollen besitzen (ein <code>RPortPrototype</code> und ein <code>PPortPrototype</code>). Zwei P-Ports oder zwei R-Ports können nicht direkt verbunden werden.</li>\n<li>Wenn die Interface-Definitionen divergieren (z. B. unterschiedliche Elementnamen oder Datentypen), verlangt das Schema zwingend ein valides <code>PortInterfaceMapping</code> (<code>[TPS_SWCT_01160]</code>, <code>[TPS_SWCT_01161]</code>), andernfalls schlägt die VFB-Validierung mit Inkompatibilitätsfehlern fehl.</li>\n<li><strong>Allokation auf ECUs (System Description vs. ECU Extract):</strong></li>\n<li>Wird das Subsystem auf eine einzige ECU gemappt, eliminiert der RTE-Generator die hierarchischen Grenzen vollständig („Flattening“).</li>\n<li>Werden die Quell- und Zielkomponenten über verschiedene ECUs verteilt, wird der Pass-Through auf die Com- bzw. Signal-Gateway-Ebene des Basis-Software-Stacks (BSW / PduR / Com) übertragen.</li>\n</ul>"}], "trans": [{"from": "FIG-602067ecaeca6343", "to": "FIG-6d6be4e06feb97e1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6d6be4e06feb97e1", "to": "FIG-602067ecaeca6343", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-602067ecaeca6343", "to": "FIG-5f57fe155affcc1b", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5f57fe155affcc1b", "to": "FIG-6d6be4e06feb97e1", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
